package dev.zomboid.isotacz;
import java.util.*;
/** Selection uses visual outlines, rather than collision shapes or the player's gun sight. */
public final class CursorTarget {
 static Object[] ray(Object mc){Object window=R.call(mc,"getWindow"),mouse=R.get(mc,"mouseHandler"),renderer=R.get(mc,"gameRenderer"),camera=R.call(renderer,"getMainCamera"),pos=R.call(camera,"getPosition");if(Bridge.projection!=null)return projectedRay(camera,pos,window,mouse);double nx=2*R.num(R.call(mouse,"xpos"))/R.num(R.call(window,"getScreenWidth"))-1,ny=1-2*R.num(R.call(mouse,"ypos"))/R.num(R.call(window,"getScreenHeight"));double aspect=R.num(R.call(window,"getWidth"))/R.num(R.call(window,"getHeight")),fov=R.num(R.call(renderer,"callGetFov",camera,(float)R.num(R.call(camera,"getPartialTickTime")),true));Rules.Ray ray=Rules.cursor(Bridge.v(pos,"x"),Bridge.v(pos,"y"),Bridge.v(pos,"z"),R.num(R.call(camera,"getYRot")),R.num(R.call(camera,"getXRot")),nx,ny,aspect,fov,R.yes(R.get(Bridge.config(),"ortho")),R.num(R.call(Bridge.mod(),"getZoom")));double[] o=ray.origin(),d=ray.direction();Object start=Bridge.vec(o[0],o[1],o[2]),end=Bridge.vec(o[0]+128*d[0],o[1]+128*d[1],o[2]+128*d[2]);return new Object[]{start,end};}
 static Object[] projectedRay(Object camera,Object pos,Object window,Object mouse){double nx=2*R.num(R.call(mouse,"xpos"))/R.num(R.call(window,"getScreenWidth"))-1,ny=1-2*R.num(R.call(mouse,"ypos"))/R.num(R.call(window,"getScreenHeight"));Object inverse=R.make("org.joml.Matrix4f",Bridge.projection);R.call(inverse,"invert");Object q=R.call(camera,"rotation");Object[] points=new Object[2];for(int i=0;i<2;i++){Object clip=R.make("org.joml.Vector4f",(float)nx,(float)ny,i==0?-1f:1f,1f);R.call(inverse,"transform",clip);double w=Bridge.v(clip,"w");Object v=R.make("org.joml.Vector3f",(float)(Bridge.v(clip,"x")/w),(float)(Bridge.v(clip,"y")/w),(float)(Bridge.v(clip,"z")/w));R.call(q,"transform",v);points[i]=Bridge.plus(pos,Bridge.v(v,"x"),Bridge.v(v,"y"),Bridge.v(v,"z"));}return points;}
 static Object aimPoint(Object mc){Object[] ray=ray(mc);Object player=R.get(mc,"player"),level=R.get(mc,"level");Object context=R.make("com.cleannrooster.dungeons_iso.api.RaycastContextCull",ray[0],ray[1],R.get(R.type("com.cleannrooster.dungeons_iso.api.CustomShapeTypes"),"CULLED"),R.get(R.type("net.minecraft.world.level.ClipContext$Block"),"OUTLINE"),R.get(R.type("net.minecraft.world.level.ClipContext$Fluid"),"NONE"),player);Object hit=R.call(level,"clip",context),point=R.call(hit,"getLocation");boolean found=!R.call(hit,"getType").toString().equals("MISS");double best=Bridge.distance(ray[0],point);Object direction=R.call(ray[1],"subtract",ray[0]),box=R.call(R.type("net.minecraft.world.phys.AABB"),"ofSize",ray[0],1d,1d,1d);box=R.call(R.call(box,"expandTowards",direction),"inflate",.1d);java.util.function.Predicate<Object> filter=e->R.yes(R.call(e,"isPickable"))&&!R.yes(R.call(e,"isSpectator"));for(Object entity:(List<?>)R.call(level,"getEntities",player,box,filter)){Optional<?> at=(Optional<?>)R.call(R.call(entity,"getBoundingBox"),"clip",ray[0],ray[1]);if(at.isPresent()&&Bridge.distance(ray[0],at.get())<best){point=at.get();best=Bridge.distance(ray[0],point);found=true;}}if(!found){double dy=Bridge.v(direction,"y"),floor=Bridge.v(R.call(player,"getEyePosition"),"y")-.8,t=Math.abs(dy)>.0001?(floor-Bridge.v(ray[0],"y"))/dy:-1;if(t>0&&t<=1)point=Bridge.plus(ray[0],Bridge.v(direction,"x")*t,dy*t,Bridge.v(direction,"z")*t);}return point;}
 static Object pick(Object mc){Object[] ray=ray(mc);return pickRay(mc,ray[0],ray[1]);}
 static Object pickRay(Object mc,Object start,Object end){return pickRay(mc,start,end,false);}
 static Object pickRay(Object mc,Object start,Object end,boolean breaking){Object player=R.get(mc,"player"),level=R.get(mc,"level"),eye=R.call(player,"getEyePosition");double range=Math.min(8,R.num(R.call(player,"blockInteractionRange")));int radius=(int)Math.ceil(range)+1,cx=(int)Math.floor(Bridge.v(eye,"x")),cy=(int)Math.floor(Bridge.v(eye,"y")),cz=(int)Math.floor(Bridge.v(eye,"z"));Object bestHit=null;double best=Double.POSITIVE_INFINITY;
  for(int x=cx-radius;x<=cx+radius;x++)for(int y=cy-radius;y<=cy+radius;y++)for(int z=cz-radius;z<=cz+radius;z++){Object pos=R.make("net.minecraft.core.BlockPos",x,y,z);if(Bridge.blockDistance(eye,pos)>range)continue;if(!Rules.rayBox(Bridge.v(start,"x"),Bridge.v(start,"y"),Bridge.v(start,"z"),Bridge.v(end,"x"),Bridge.v(end,"y"),Bridge.v(end,"z"),x,y,z))continue;Object state=R.call(level,"getBlockState",pos);if(R.yes(R.call(state,"isAir"))||hidden(mc,state,pos))continue;boolean remains=Bridge.remains(Bridge.blockId(state));if(!breaking&&!remains&&!R.yes(R.call(R.type("com.cleannrooster.dungeons_iso.util.InteractionTargeting"),"isInteractable",level,pos)))continue;Object shape=R.call(state,"getShape",level,pos),box;
   if(R.yes(R.call(shape,"isEmpty"))){if(!remains)continue;box=R.make("net.minecraft.world.phys.AABB",(double)x-.1,(double)y,(double)z-.1,(double)x+1.1,(double)y+.35,(double)z+1.1);}else box=R.call(R.call(shape,"bounds"),"move",(double)x,(double)y,(double)z);
   Optional<?> point=(Optional<?>)R.call(box,"clip",start,end);if(point.isEmpty())continue;double d=Bridge.distance(start,point.get());if(d>=best)continue;Object hit=R.yes(R.call(shape,"isEmpty"))?R.make("net.minecraft.world.phys.BlockHitResult",point.get(),R.get(R.type("net.minecraft.core.Direction"),"UP"),pos,false):R.call(shape,"clip",start,end,pos);if(hit==null)continue;if(breaking?reachable(mc,eye,hit):Bridge.interactable(mc,hit)){best=d;bestHit=hit;}
  }
  Object box=R.call(R.type("net.minecraft.world.phys.AABB"),"ofSize",start,1d,1d,1d);box=R.call(R.call(box,"expandTowards",R.call(end,"subtract",start)),"inflate",.4d);java.util.function.Predicate<Object> filter=Bridge::corpse;
  for(Object entity:(List<?>)R.call(level,"getEntities",player,box,filter)){Object bounds=R.call(R.call(entity,"getBoundingBox"),"inflate",.25d);Optional<?> point=(Optional<?>)R.call(bounds,"clip",start,end);if(point.isEmpty())continue;double d=Bridge.distance(start,point.get());if(d>=best)continue;Object hit=R.make("net.minecraft.world.phys.EntityHitResult",entity,point.get());if(breaking?reachable(mc,eye,hit):Bridge.interactable(mc,hit)){best=d;bestHit=hit;}}
  return bestHit;
 }
 static boolean hidden(Object mc,Object state,Object pos){Object terrain=R.type("com.cleannrooster.dungeons_iso.api.cullers.room.TerrainCulling");if(R.yes(R.call(terrain,"shouldRemove",state,(int)R.coord(pos,"X"),(int)R.coord(pos,"Y"),(int)R.coord(pos,"Z"))))return true;Object camera=R.call(R.get(mc,"gameRenderer"),"getMainCamera"),player=R.get(mc,"player");for(Object culler:(Iterable<?>)R.get(R.type("com.cleannrooster.dungeons_iso.compat.SodiumCompat"),"blockCullersShapes"))if(R.yes(R.call(culler,"shouldCull",pos,camera,player))||R.yes(R.call(culler,"shouldIgnoreBlockPick",pos,camera,player)))return true;return false;}
 static boolean reachable(Object mc,Object eye,Object hit){Object point=R.call(hit,"getLocation"),obstruction=Bridge.clip(R.get(mc,"level"),R.get(mc,"player"),eye,point);return !R.call(obstruction,"getType").toString().equals("BLOCK")||R.call(hit,"getType").toString().equals("BLOCK")&&R.call(hit,"getBlockPos").equals(R.call(obstruction,"getBlockPos"))||Bridge.distance(eye,R.call(obstruction,"getLocation"))>=Bridge.distance(eye,point)-.05;}
}
